import datetime
try:
    now = datetime.datetime.fromisoformat(str(vars.get('now'))[:16])
    t = now.date()
    hol = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
    bds = []
    d = t
    while len(bds) < 12:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5 and d.isoformat() not in hol:
            bds.append(d)
    a1 = t + datetime.timedelta(days=4 - t.weekday())
    while a1.weekday() > 4 or a1.isoformat() in hol:
        a1 = a1 - datetime.timedelta(days=1)
    if a1 <= t:
        a1 = t + datetime.timedelta(days=11 - t.weekday())
        while a1.weekday() > 4 or a1.isoformat() in hol:
            a1 = a1 - datetime.timedelta(days=1)
    f = '%A %Y-%m-%d'
    mon = t - datetime.timedelta(days=t.weekday())
    wk = ['this week', 'next week', 'week after next', 'in three weeks']
    cal = []
    for i in range(24):
        d = t + datetime.timedelta(days=i)
        if d.isoformat() in hol:
            k = 'Freya Bank holiday'
        elif d.weekday() > 4:
            k = 'weekend'
        else:
            k = 'business day'
        cal.append(d.strftime(f) + ' (' + wk[min((d - mon).days // 7, 3)] + '): ' + k)
    tb = t.weekday() < 5 and t.isoformat() not in hol
    head = ['Today: ' + t.strftime(f) + ', time now ' + now.strftime('%H:%M') + ('' if tb else ' (not a business day)'), 'Next business day: ' + bds[0].strftime(f), 'Deadline, early band (days_late 1 to 7, 12th business day after today): ' + bds[11].strftime(f), 'Deadline, late band (days_late 8 to 45, 7th business day after today): ' + bds[6].strftime(f), 'Attempt 1 date (last business day of this week, or of next week if today is that day): ' + a1.strftime(f), 'Calendar:']
    vars['date_facts'] = '\n'.join(head + cal)
except Exception:
    vars['date_facts'] = 'Date facts could not be computed. Now is ' + str(vars.get('now')) + '. Business days are Monday to Friday except 2026-10-26, 2026-11-11, 2026-11-26, 2026-12-25, 2027-01-01.'

